package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	s := strings.TrimSpace(string(data))
	n := len(s)
	var ans int64
	// Manacher: d1 = odd radii, d2 = even radii; each radius counts that many palindromes.
	d1, d2 := make([]int, n), make([]int, n)
	for i, l, r := 0, 0, -1; i < n; i++ {
		k := 1
		if i <= r {
			k = min(d1[l+r-i], r-i+1)
		}
		for i-k >= 0 && i+k < n && s[i-k] == s[i+k] {
			k++
		}
		d1[i] = k
		ans += int64(k)
		if i+k-1 > r {
			l, r = i-k+1, i+k-1
		}
	}
	for i, l, r := 0, 0, -1; i < n; i++ {
		k := 0
		if i <= r {
			k = min(d2[l+r-i+1], r-i+1)
		}
		for i-k-1 >= 0 && i+k < n && s[i-k-1] == s[i+k] {
			k++
		}
		d2[i] = k
		ans += int64(k)
		if i+k-1 > r {
			l, r = i-k, i+k-1
		}
	}
	fmt.Println(ans)
}
